cat > /tmp/pi.c <<'C'
#include <stdio.h>
typedef struct { double kp, ki, limit, integral; } PI;
double pi_step(PI *p, double error, double dt) {
    double proposed = p->integral + p->ki * error * dt;
    double raw = p->kp * error + proposed;
    if (raw > p->limit) { p->integral = proposed > p->integral ? p->integral : proposed; return p->limit; }
    if (raw < -p->limit) { p->integral = proposed < p->integral ? p->integral : proposed; return -p->limit; }
    p->integral = proposed; return raw;
}
int main(void) {
    PI c = {0.4, 1000.0, 24.0, 0.0};
    double i = 0.0;
    for (int k = 0; k < 2000; k++) { double u = pi_step(&c, 2.0 - i, 1e-3); i += (u - 2.0 * i) / 0.002 * 1e-3; }
    printf("final current = %.6f A\n", i);
    return 0;
}
C
gcc -O2 -o /tmp/pi /tmp/pi.c && /tmp/pi
